/* Milestone Glowing Base & Rotating Rings */
.milestone-base {
  position: absolute;
  top: 75px; /* placed below the 60px height button */
  left: 36px;
  width: 140px;
  height: 140px;
  transform: translate(-50%, -50%) rotateX(65deg);
  z-index: 1;
  pointer-events: none;
  opacity: 0.9;
}

.milestone-base .ring {
  position: absolute;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.milestone-base .ring-core {
  width: 50px;
  height: 50px;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 0 30px 15px currentColor;
}

.milestone-base .ring-inner {
  width: 90px;
  height: 90px;
  border: 10px solid currentColor;
  opacity: 0.8;
  border-left-color: transparent;
  animation: ring-spin 4s linear infinite;
}

.milestone-base .ring-outer {
  width: 130px;
  height: 130px;
  border: 3px solid currentColor;
  opacity: 0.5;
  border-right-color: transparent;
  border-bottom-color: transparent;
  animation: ring-spin-reverse 6s linear infinite;
}

@keyframes ring-spin {
  100% { transform: translate(-50%, -50%) rotate(360deg); }
}
@keyframes ring-spin-reverse {
  100% { transform: translate(-50%, -50%) rotate(-360deg); }
}

.milestone-base.current { color: #3b82f6; }
.milestone-base.done { color: #fbbf24; }
.milestone-base.locked { color: #94a3b8; opacity: 0.2; }
.milestone-base.locked .ring-inner, .milestone-base.locked .ring-outer { animation: none; }

